_sgt_replace_owned_file() {
  local path="$1" value="$2" candidate
  candidate="${path}.tmp.$$.$RANDOM.$RANDOM"
  (umask 077; set -C; printf '%s\n' "$value" > "$candidate") 2>/dev/null || return 1
